class Solution {
public:
    int ways(vector<string>& pizza, int k) {
        int rows = (int)pizza.size();
        int cols = (int)pizza[0].size();
        const int MOD = 1000000007;

        // 2-D prefix sum of apple counts.
        // ps[i][j] = apples in pizza[0..i-1][0..j-1]
        vector<vector<int>> ps(rows + 1, vector<int>(cols + 1, 0));
        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < cols; ++j) {
                ps[i+1][j+1] = ps[i][j+1] + ps[i+1][j] - ps[i][j]
                               + (pizza[i][j] == 'A' ? 1 : 0);
            }
        }

        auto hasApple = [&](int r1, int c1, int r2, int c2) -> bool {
            int cnt = ps[r2+1][c2+1] - ps[r1][c2+1] - ps[r2+1][c1] + ps[r1][c1];
            return cnt > 0;
        };

        // dp[r][c][cuts] = number of ways to finish when the current piece
        // has upper-left (r,c), lower-right (rows-1, cols-1), and `cuts`
        // cuts still to make.
        vector<vector<vector<int>>> dp(rows,
            vector<vector<int>>(cols, vector<int>(k, -1)));

        function<int(int,int,int)> solve = [&](int r, int c, int cuts) -> int {
            if (!hasApple(r, c, rows-1, cols-1)) return 0;
            if (cuts == 0) return 1;
            int& memo = dp[r][c][cuts];
            if (memo != -1) return memo;

            long long total = 0;
            // Horizontal cut after row i: give away rows r..i (upper part).
            for (int i = r; i < rows - 1; ++i) {
                if (hasApple(r, c, i, cols-1)) {
                    total += solve(i+1, c, cuts-1);
                }
            }
            // Vertical cut after col j: give away cols c..j (left part).
            for (int j = c; j < cols - 1; ++j) {
                if (hasApple(r, c, rows-1, j)) {
                    total += solve(r, j+1, cuts-1);
                }
            }

            memo = (int)(total % MOD);
            return memo;
        };

        return solve(0, 0, k - 1);
    }
};
